**Gates before launch**

I run five gates before I launch, and each one must pass.
1. I confirm with `git status` and `git log` that `spe/predictions/r04.yaml` and `spe/plans/r04.md` are committed and unchanged since that commit.
2. I save the script as `spe/evals/harness/r04-workflow.js`. I diff it against `spe/evals/harness/r03-workflow.js` so that only the round 4 changes differ. Then I make a local commit of the script, with no push.
3. I test the grader. I run `spe/evals/graders/grade.py` on two small fixtures. In one fixture every `label.category` and `label.priority` matches `spe/evals/tasks/answers.json`, so it must score 100%. In the other fixture every label is wrong, so it must score 0%.
4. I check the configs and the judge. Both config prompts must be exactly 12 lines. B must expose 6 tools. C2 must expose 3 tools plus `check_status`. `spe/evals/graders/judge.md` must load.
5. I do a dry run of 1 ticket and 1 trial per config. This measures `estTrialUsd` and `estJudgeUsd`. I launch only if the script's projected total stays under $40 and `spe/evals/runs/r04/` is empty.

I assumed the round 3 runner and grader interfaces. The runner is `node spe/evals/harness/run-trial.js --config --ticket --trial --out`, and it prints JSON with the label, reply, and `cost_usd`. The grader takes `--answers`, `--runs`, and `--json`. Both commands can be overridden through `args`. One choice is mine and not in the plan. The judge scores each ticket's 10 replies in one Opus call, with the replies shuffled and their configs hidden. That makes 50 judge calls instead of 500, which keeps the run under the cap.

**Script (`spe/evals/harness/r04-workflow.js`)**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4: configs B and C2, 50 tickets x 5 trials, code grader on label.category and label.priority, blinded Opus tone judge, $40 spend cap',
  phases: [
    { title: 'Preflight' },
    { title: 'Trials and judging' },
    { title: 'Code grading' },
    { title: 'Summary' },
  ],
};

// ---- Fixed by the approved round 4 plan ----
const CONFIGS = ['B', 'C2'];
const TRIALS = 5;
const EXPECTED_TICKETS = 50;
const CAP_USD = 40;
const MODEL = 'opus';
const RUN_DIR = 'spe/evals/runs/r04';
const ANSWERS = 'spe/evals/tasks/answers.json';
const GRADER = 'spe/evals/graders/grade.py';
const JUDGE_RUBRIC = 'spe/evals/graders/judge.md';

// ---- Set from the dry run and preflight gates ----
const a = (typeof args === 'object' && args) || {};
const RUNNER = a.runner ?? 'node spe/evals/harness/run-trial.js';
const GRADE_CMD = a.gradeCmd ?? `python3 ${GRADER} --answers ${ANSWERS} --runs ${RUN_DIR} --json`;
const EST_TRIAL_USD = a.estTrialUsd;            // runner cost of one trial, from the dry run
const EST_JUDGE_USD = a.estJudgeUsd;            // cost of one per-ticket judge call, from the dry run
const AGENT_OVERHEAD_USD = a.agentOverheadUsd ?? 0.05; // orchestration cost per agent call
const WAVE = a.waveSize ?? 10;                  // tickets per wave
const SEED = a.seed ?? 4;
const MAX_INFRA_ERROR_RATE = a.maxInfraErrorRate ?? 0.1;

if (typeof EST_TRIAL_USD !== 'number' || typeof EST_JUDGE_USD !== 'number') {
  throw new Error('args.estTrialUsd and args.estJudgeUsd are required. Measure them in the dry run first.');
}

// Cost of one ticket: 2 trial agents (5 trials each) plus 1 judge agent.
const PER_TICKET_USD =
  CONFIGS.length * (TRIALS * EST_TRIAL_USD + AGENT_OVERHEAD_USD) + EST_JUDGE_USD + AGENT_OVERHEAD_USD;
const PROJECTED_USD = EXPECTED_TICKETS * PER_TICKET_USD + 2 * AGENT_OVERHEAD_USD;
if (PROJECTED_USD > CAP_USD) {
  throw new Error(`Projected spend $${PROJECTED_USD.toFixed(2)} exceeds cap $${CAP_USD}. Not launching.`);
}

// ---- Helpers ----
function mulberry32(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffle(xs, rand) {
  const out = xs.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
const rand = mulberry32(SEED);
let spentUsd = 0;
const errors = [];

// ---- Schemas ----
const preflightSchema = {
  type: 'object',
  required: ['ok', 'head_sha', 'ticket_ids', 'problems'],
  properties: {
    ok: { type: 'boolean' },
    head_sha: { type: 'string' },
    ticket_ids: { type: 'array', items: { type: 'string' } },
    problems: { type: 'array', items: { type: 'string' } },
  },
};
const trialsSchema = {
  type: 'object',
  required: ['ticket_id', 'config', 'trials'],
  properties: {
    ticket_id: { type: 'string' },
    config: { type: 'string' },
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'ok', 'output_path', 'cost_usd'],
        properties: {
          trial: { type: 'integer' },
          ok: { type: 'boolean' },
          output_path: { type: 'string' },
          category: { type: ['string', 'null'] },
          priority: { type: ['string', 'null'] },
          reply: { type: ['string', 'null'] },
          cost_usd: { type: 'number' },
          error: { type: ['string', 'null'] },
        },
      },
    },
  },
};
const judgeSchema = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'score', 'rationale'],
        properties: {
          id: { type: 'string' },
          score: { type: 'number' },
          rationale: { type: 'string' },
        },
      },
    },
  },
};
const gradeSchema = {
  type: 'object',
  required: ['ok', 'cells'],
  properties: {
    ok: { type: 'boolean' },
    raw_stdout: { type: 'string' },
    cells: {
      type: 'array',
      items: {
        type: 'object',
        required: ['config', 'n', 'missing', 'category_acc', 'priority_acc', 'both_acc'],
        properties: {
          config: { type: 'string' },
          n: { type: 'integer' },
          missing: { type: 'integer' },
          category_acc: { type: 'number' },
          priority_acc: { type: 'number' },
          both_acc: { type: 'number' },
        },
      },
    },
  },
};

// ---- Phase 1: Preflight ----
phase('Preflight');
log(`Projected spend $${PROJECTED_USD.toFixed(2)} of $${CAP_USD} cap. Per ticket $${PER_TICKET_USD.toFixed(3)}.`);

const pre = await agent(
  `You are the preflight check for SPE round 4. Do not modify any file. Do not commit.
Check each item and report problems as short strings:
1. These files exist: ${GRADER}, ${ANSWERS}, ${JUDGE_RUBRIC}, and the runner named by "${RUNNER}".
2. "git status --porcelain spe/predictions/r04.yaml spe/plans/r04.md" prints nothing, and both files are tracked in HEAD.
3. The directory ${RUN_DIR} is absent or empty.
4. Read the ticket IDs from ${ANSWERS}. Return the IDs only. Do not return or summarize any answers.
Return head_sha from "git rev-parse HEAD". Set ok to true only if every check passes and there are exactly ${EXPECTED_TICKETS} ticket IDs.`,
  { label: 'preflight', phase: 'Preflight', schema: preflightSchema, model: MODEL },
);
spentUsd += AGENT_OVERHEAD_USD;

if (!pre.ok || pre.ticket_ids.length !== EXPECTED_TICKETS) {
  throw new Error(`Preflight failed: ${JSON.stringify(pre.problems)} (tickets: ${pre.ticket_ids.length})`);
}
log(`Preflight passed at ${pre.head_sha}. ${pre.ticket_ids.length} tickets.`);

// ---- Phase 2: Trials and judging ----
phase('Trials and judging');

function runTrials(ticketId, config) {
  return agent(
    `You run SPE round 4 trials. You are an operator. You are not the system under test.
Do not read ${ANSWERS}, ${GRADER}, or ${JUDGE_RUBRIC}. Do not edit any config or harness file.
For trial in 1..${TRIALS}, run exactly:
  ${RUNNER} --config ${config} --ticket ${ticketId} --trial <trial> --out ${RUN_DIR}/${config}/${ticketId}/t<trial>.json
Run the trials one after another. Do not retry a trial that returns a wrong answer.
Retry once only if the runner itself crashes before it writes output. Record the crash text in "error".
For each trial, copy from the runner's JSON output: label.category into category, label.priority into priority, the reply text into reply, and cost_usd.
Set ok to false if the output file is missing or unparseable.`,
    {
      label: `trial ${config} ${ticketId}`,
      phase: 'Trials and judging',
      schema: trialsSchema,
      model: MODEL,
    },
  );
}

function judgeTicket(ticketId, blinded) {
  const block = blinded.map((r) => `### ${r.id}\n${r.reply}`).join('\n\n');
  return agent(
    `You are the reply-tone judge for SPE round 4. Read the rubric at ${JUDGE_RUBRIC} and apply it exactly.
Do not read any other file under spe/. You do not know which system wrote each reply. Do not guess.
Score each reply on its own against the rubric. Do not rank the replies against each other.
Ticket: ${ticketId}

${block}

Return one entry per reply id, using the rubric's scale, with a one-sentence rationale.`,
    { label: `judge ${ticketId}`, phase: 'Trials and judging', schema: judgeSchema, model: MODEL },
  );
}

async function processTicket(ticketId) {
  const results = await parallel(
    CONFIGS.map((config) => async () => {
      try {
        const r = await runTrials(ticketId, config);
        spentUsd += AGENT_OVERHEAD_USD + r.trials.reduce((s, t) => s + (t.cost_usd || 0), 0);
        return r;
      } catch (e) {
        spentUsd += AGENT_OVERHEAD_USD;
        errors.push({ ticketId, config, stage: 'trials', error: String(e) });
        return { ticket_id: ticketId, config, trials: [] };
      }
    }),
  );

  // Blind the replies. Shuffle them across configs and give each a neutral id.
  const replies = [];
  for (const r of results) {
    for (const t of r.trials) {
      if (t.ok && t.reply) replies.push({ config: r.config, trial: t.trial, reply: t.reply });
    }
  }
  const blinded = shuffle(replies, rand).map((r, i) => ({ ...r, id: `r${String(i + 1).padStart(2, '0')}` }));

  let judged = [];
  if (blinded.length > 0) {
    try {
      const j = await judgeTicket(ticketId, blinded.map(({ id, reply }) => ({ id, reply })));
      spentUsd += EST_JUDGE_USD + AGENT_OVERHEAD_USD;
      const key = Object.fromEntries(blinded.map((b) => [b.id, b]));
      judged = j.scores
        .filter((s) => key[s.id])
        .map((s) => ({ ticketId, config: key[s.id].config, trial: key[s.id].trial, score: s.score, rationale: s.rationale }));
    } catch (e) {
      spentUsd += AGENT_OVERHEAD_USD;
      errors.push({ ticketId, stage: 'judge', error: String(e) });
    }
  }
  return { ticketId, trials: results, judged };
}

const order = shuffle(pre.ticket_ids, rand);
const done = [];
let stopReason = null;

for (let i = 0; i < order.length; i += WAVE) {
  const wave = order.slice(i, i + WAVE);
  const nextWaveUsd = wave.length * PER_TICKET_USD;
  if (spentUsd + nextWaveUsd > CAP_USD) {
    stopReason = `Budget: spent $${spentUsd.toFixed(2)}. The next wave would need $${nextWaveUsd.toFixed(2)} and cross the $${CAP_USD} cap.`;
    log(stopReason);
    break;
  }
  const out = await parallel(wave.map((t) => () => processTicket(t)));
  done.push(...out);

  const trialsInWave = out.flatMap((o) => o.trials.flatMap((r) => r.trials));
  const infraFails = trialsInWave.filter((t) => !t.ok).length;
  const expected = wave.length * CONFIGS.length * TRIALS;
  const missing = expected - trialsInWave.length;
  const rate = (infraFails + missing) / expected;
  log(`Wave ${i / WAVE + 1}: ${out.length} tickets. Infra failures ${infraFails + missing}/${expected}. Spent $${spentUsd.toFixed(2)}.`);
  if (rate > MAX_INFRA_ERROR_RATE) {
    stopReason = `Infra error rate ${(rate * 100).toFixed(1)}% exceeded ${MAX_INFRA_ERROR_RATE * 100}% in wave ${i / WAVE + 1}.`;
    log(stopReason);
    break;
  }
}

// ---- Phase 3: Code grading ----
phase('Code grading');
const grade = await agent(
  `Run this command exactly and do nothing else:
  ${GRADE_CMD}
Do not edit ${GRADER}, ${ANSWERS}, or any file under ${RUN_DIR}.
Copy the grader's per-config numbers into "cells" without recomputing them. Put the full stdout in raw_stdout.
"missing" means expected trial outputs with no file: ${CONFIGS.length} configs x ${EXPECTED_TICKETS} tickets x ${TRIALS} trials, split per config.
Set ok to false if the command exits non-zero.`,
  { label: 'grade', phase: 'Code grading', schema: gradeSchema, model: MODEL },
);
spentUsd += AGENT_OVERHEAD_USD;

// ---- Phase 4: Summary ----
phase('Summary');
const judgedAll = done.flatMap((d) => d.judged);
const tone = Object.fromEntries(
  CONFIGS.map((c) => {
    const xs = judgedAll.filter((j) => j.config === c).map((j) => j.score);
    const mean = xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null;
    return [c, { n: xs.length, mean }];
  }),
);

const complete = done.length === EXPECTED_TICKETS && !stopReason && grade.ok;
log(`Round 4 ${complete ? 'complete' : 'INCOMPLETE'}. Tickets ${done.length}/${EXPECTED_TICKETS}. Spent about $${spentUsd.toFixed(2)} of $${CAP_USD}.`);

return {
  round: 'r04',
  head_sha: pre.head_sha,
  seed: SEED,
  complete,
  stop_reason: stopReason,
  tickets_run: done.length,
  ticket_order: order.slice(0, done.length),
  spend: { estimated_usd: Number(spentUsd.toFixed(2)), cap_usd: CAP_USD, projected_usd: Number(PROJECTED_USD.toFixed(2)) },
  grader: grade,
  tone,
  judged: judgedAll,
  errors,
};
```
